                  if source[r][c] == color}
        for dr, dc in ((1, -1), (1, 1)):
            for r, c in coords:
                if (r - dr, c - dc) in coords:
                    continue
                run = []
                rr, cc = r, c
                while (rr, cc) in coords:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for sr, sc, step_r, step_c in (
